	}
	if gotItems[1].Call.Name != "read" || string(gotItems[1].Call.Args) != `{"path":"x"}` {
		t.Fatalf("tool call not preserved: %+v", gotItems[1])
	}
	if gotItems[2].Result.Content != "data" {
		t.Fatalf("tool result not preserved: %+v", gotItems[2])
	}
}

